mapper.select:
SELECT id, order_id, identity_key, guest_name, phone, age, party_type, inferred_region, tags, admin_remark
FROM booker_profile
WHERE identity_key = #{identityKey}

SELECT id, order_id, identity_key, guest_name, phone, age, party_type, inferred_region, tags, admin_remark
FROM booker_profile
WHERE id = #{id}

mapper.update:
UPDATE booker_profile
SET age = #{age}, party_type = #{partyType}, inferred_region = #{inferredRegion},
    tags = CAST(#{tagsJson} AS JSON), admin_remark = #{adminRemark}
WHERE id = #{id}

UPDATE orders
SET remark = #{remark}, admin_remark = #{adminRemark}, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{orderId}

mapper.select:
SELECT profile.id, profile.guest_name, profile.phone, profile.age, profile.party_type, profile.inferred_region, profile.tags, profile.admin_remark, (member.id IS NOT NULL) AS member, COALESCE(summary.completed_order_count, 0) AS completed_order_count, COALESCE(summary.cumulative_paid_amount, 0.00) AS cumulative_paid_amount FROM booker_profile AS profile LEFT JOIN members AS member ON member.phone = profile.phone LEFT JOIN ( SELECT profile.id AS profile_id, COUNT(order_row.id) AS completed_order_count, SUM(amount.paid_amount) AS cumulative_paid_amount FROM booker_profile AS profile INNER JOIN orders AS order_row ON INNER JOIN order_amount AS amount ON amount.order_id = order_row.id WHERE order_row.status = 'COMPLETED' GROUP BY profile.id ) AS summary ON summary.profile_id = profile.id
AND EXISTS ( SELECT 1 FROM orders AS order_row WHERE )
ORDER BY profile.updated_at DESC, profile.id DESC LIMIT #{query.size} OFFSET #{offset}

SELECT profile.id AS profile_id, order_row.id AS order_id, order_row.order_no, order_row.check_in, amount.paid_amount, order_row.status, order_row.remark, order_row.admin_remark FROM booker_profile AS profile INNER JOIN orders AS order_row ON INNER JOIN order_amount AS amount ON amount.order_id = order_row.id WHERE order_row.status = 'COMPLETED' AND profile.id IN
#{profileId}
ORDER BY order_row.check_in DESC, order_row.id DESC

SELECT profile.id AS profile_id, order_row.id AS order_id, order_row.order_no, order_row.check_in, order_row.status, order_row.remark, order_row.admin_remark FROM booker_profile AS profile INNER JOIN orders AS order_row ON WHERE profile.id IN
#{profileId}
ORDER BY order_row.created_at DESC, order_row.id DESC
